	waitRetry := c.waitCommunityRetry
	if waitRetry == nil {
		waitRetry = func(ctx context.Context, interval time.Duration) bool {
			timer := time.NewTimer(interval)
			defer timer.Stop()
			select {
			case <-ctx.Done():
				return false
			case <-timer.C:
				return true
			}
		}
	}

	var generationID uint64
	for ctx.Err() == nil {
		generationID++
